Lemma rmrep_set_area_next : forall st m m' a ar p,
  rmrep st m -> (s_areas st) !! a = Some ar -> is_Some ((s_regions st) !! (fst p)) ->
  munch [(conc st a + 8, conc st a + 16)]%Z m m' -> wmono usegs m m' ->
  rw_cells usegs m' (conc st a) [C8 (wz (a_check ar)); C8 (wz (conc st p)); C4 (wz (a_nslots ar)); C4 (wz 0)] ->
  rmrep (set_areas (<[a := mkArea (a_check ar) (Some p) (a_nslots ar)]> (s_areas st)) st) m'.
Proof. try hcb. try hsb.
  intros st m m' a ar p MR Ha Hp MU WM CH.
  pose proof MR as (WF & CTX & GL & AR & GR & SH).
  pose proof WF as (RS & RW & RD & RA & RG).
  destruct (RA a ar Ha) as (ra & Hra & Sa0 & Sa4 & Sam & Hka & LLa).
  destruct (RW (fst a) ra Hra) as (RB0 & RBm & RL0 & RBC & RF).
  pose proof (rreserved_disjoint _ _ RF) as (D1 & D2 & D3 & D4).
  pose proof (round_up_pg_ge (r_len ra)) as RU.
  assert (CR : forall q rq, (s_regions st) !! (fst q) = Some rq -> conc st q = r_base rq + snd q)
    by (intros q rq E; unfold conc, get_region; rewrite E; reflexivity).
  pose proof (CR a ra Hra) as HA.
  set (A := conc st a) in *.
  assert (EA : A = conc st a) by reflexivity.
  set (CW := fun x : Z => A + 8 <= x < A + 16).
  assert (PE : rpres_except CW m m').
  { apply (rpres_except_of_munch CW [(A + 8, A + 16)] m m' MU WM).
    intros x _ Hx. split; [exact Hx | exact I]. }
  assert (AG : forall B n, 0 <= B -> B + n <= 2^64 -> (B + n <= A + 8 \/ A + 16 <= B) -> agree_on m m' B n).
  { intros B n H0 H1 H2.
    apply (OSSVerify.Proofs.boost_beast.http_request.lib.Ub.RMallocKit_B2.rpres_except_agree CW m m' B n PE H0 H1).
    intros x Hx HC. unfold CW in HC. lia. }
  assert (RWT : forall B cs, rw_cells usegs m B cs ->
                  (B + Z.of_nat (cells_size cs) <= A + 8 \/ A + 16 <= B) -> rw_cells usegs m' B cs).
  { intros B cs H D. pose proof (rw_cells_bound _ _ _ _ H) as [H0 H1].
    apply (OSSVerify.Proofs.boost_beast.http_request.lib.Ub.RMallocKit_B2.rrw_cells_agree' m m' B cs H).
    apply AG; assumption. }
  assert (BAND : forall B n, 0x10000 <= B -> B + n <= 0xb8000 -> 0 <= n -> B + n <= A + 8 \/ A + 16 <= B)
    by (intros; lia).
  assert (AGI : forall B n, 0x10000 <= B -> B + n <= 0xb8000 -> 0 <= n -> agree_on m m' B n)
    by (intros B n H0 H1 H2; apply AG; [lia | lia | apply BAND; assumption]).
  assert (SZH : forall x y z, Z.of_nat (cells_size [C8 x; C8 y; C4 z; C4 (wz 0)]) = 24) by (intros; reflexivity).
  assert (SZM : forall mr, Z.of_nat (cells_size (meta_cells st mr)) = 40) by (intros; reflexivity).
  assert (SZT : Z.of_nat (cells_size [CB 32 (zeros 32)]) = 32) by reflexivity.
  assert (SZG : forall x y, Z.of_nat (cells_size [C8 x; C1 y]) = 9) by (intros; reflexivity).
  assert (SZ1 : forall x, Z.of_nat (cells_size [C1 x]) = 1) by (intros; reflexivity).
  assert (SZ4 : forall x, Z.of_nat (cells_size [C4 x]) = 4) by (intros; reflexivity).
  assert (SZ8 : forall x, Z.of_nat (cells_size [C8 x]) = 8) by (intros; reflexivity).
  set (ar' := mkArea (a_check ar) (Some p) (a_nslots ar)).
  set (st' := set_areas (<[a := ar']> (s_areas st)) st).
  assert (SA : s_areas st' = <[a := ar']> (s_areas st)) by reflexivity.
  unfold rmrep. split; [|split; [|split; [|split; [|split]]]].
  - unfold rregions_wf. split; [exact RS|]. split; [exact RW|]. split; [exact RD|]. split; [|exact RG].
    intros a0 ar0 Ha0. rewrite SA in Ha0. destruct (decide (a0 = a)) as [->|Hne].
    + exact (RA a ar Ha).
    + rewrite lookup_insert_ne in Ha0 by congruence. exact (RA a0 ar0 Ha0).
  - change (rmrep_ctx st m'). destruct CTX as (X1 & X2 & X3 & X4 & X5 & X6). unfold rmrep_ctx.
    assert (SZC : Z.of_nat (cells_size (ctx_head_cells st)) = 80) by reflexivity.
    assert (SZA : 8 * Z.of_nat (length (actives st)) = 384) by reflexivity.
    assert (SZU : 8 * Z.of_nat (length (usages st)) = 384) by reflexivity.
    assert (SZS : Z.of_nat (length (unmap_seqs st)) = 32) by reflexivity.
    assert (SZB : Z.of_nat (length (bouncess st)) = 32) by reflexivity.
    assert (SZL : Z.of_nat (cells_size (ctx_tail_cells st)) = 16) by reflexivity.
    split; [|split; [|split; [|split; [|split]]]].
    + apply (OSSVerify.Proofs.boost_beast.http_request.lib.Ub.RMallocKit_B2.rrw_cells_agree' m m' _ _ X1).
      rewrite SZC. apply AGI; try unfold RCTX; lia.
    + apply (OSSVerify.Proofs.boost_beast.http_request.lib.Ub.RMallocKit_B2.ru64arr_agree' m m' _ _ X2).
      rewrite SZA. apply AGI; try unfold RCTX; lia.
    + apply (OSSVerify.Proofs.boost_beast.http_request.lib.Ub.RMallocKit_B2.ru64arr_agree' m m' _ _ X3).
      rewrite SZU. apply AGI; try unfold RCTX; lia.
    + apply (OSSVerify.Proofs.boost_beast.http_request.lib.Ub.RMallocKit_B2.ru8arr_agree' m m' _ _ X4).
      rewrite SZS. apply AGI; try unfold RCTX; lia.
    + apply (OSSVerify.Proofs.boost_beast.http_request.lib.Ub.RMallocKit_B2.ru8arr_agree' m m' _ _ X5).
      rewrite SZB. apply AGI; try unfold RCTX; lia.
    + apply (OSSVerify.Proofs.boost_beast.http_request.lib.Ub.RMallocKit_B2.rrw_cells_agree' m m' _ _ X6).
      rewrite SZL. apply AGI; try unfold RCTX; lia.
  - destruct GL as (G1 & G2 & G3 & G4 & G5 & G6). unfold rmrep_globals.
    split; [|split; [|split; [|split; [|split]]]];
      (apply RWT; [eassumption|]; apply BAND; rewrite ?SZ1, ?SZ4, ?SZ8;
       try unfold RMLOCK; try unfold RNEED_LOCKS; try unfold RPAGE_SIZE; try unfold RGOT_SSP;
       try unfold RSSP_GUARD; lia).
  - red. intros a0 ar0 Ha0. rewrite SA in Ha0.
    destruct (decide (a0 = a)) as [->|Hne].
    + rewrite lookup_insert_eq in Ha0. assert (ar0 = ar') by congruence. subst ar0.
      change (rarea_rep st m' a ar').
      destruct (AR a ar Ha) as (H1 & H2 & H3). split; [exact CH|split].
      * intros k Hk. apply RWT; [exact (H2 k Hk)|]. rewrite SZM.
        unfold AREA_HDR, META_SIZE, NSLOTS in *. lia.
      * apply RWT; [exact H3|]. rewrite SZT. lia.
    + rewrite lookup_insert_ne in Ha0 by congruence.
      change (rarea_rep st m' a0 ar0).
      destruct (RA a0 ar0 Ha0) as (rb & Hrb & Sb0 & Sb4 & Sbm & Hkb & LLb).
      pose proof (CR a0 rb Hrb) as HB. pose proof (round_up_pg_ge (r_len rb)).
      assert (DJ : conc st a0 + 4096 <= A + 8 \/ A + 16 <= conc st a0).
      { destruct (N.eq_dec (fst a0) (fst a)) as [E|E].
        - rewrite E, Hra in Hrb. assert (rb = ra) by congruence. subst rb.
          assert (snd a0 <> snd a) by (intros E2; apply Hne; apply injective_projections; [exact E | exact E2]).
          pose proof (Z.div_mod (snd a0) 4096 ltac:(lia)). pose proof (Z.div_mod (snd a) 4096 ltac:(lia)).
          lia.
        - destruct (RD _ _ _ _ Hrb Hra E) as [D|D]; lia. }
      destruct (AR a0 ar0 Ha0) as (H1 & H2 & H3). split; [|split].
      * apply RWT; [exact H1|]. rewrite SZH. lia.
      * intros k Hk. apply RWT; [exact (H2 k Hk)|]. rewrite SZM.
        unfold AREA_HDR, META_SIZE, NSLOTS in *. lia.
      * apply RWT; [exact H3|]. rewrite SZT. lia.
  - change (rmrep_groups st m'). red. intros b gb Hb.
    destruct (RG b gb Hb) as (rb & Hrb & Hkb & Sb0 & Sb16 & Sbm).
    pose proof (CR b rb Hrb) as HB. pose proof (round_up_pg_ge (r_len rb)).
    assert (E : fst b <> fst a) by (intros E; rewrite E, Hra in Hrb; congruence).
    destruct (GR b gb Hb) as (w8 & G1 & G2). exists w8. split; [|exact G2].
    apply RWT; [exact G1|]. rewrite SZG.
    destruct (RD _ _ _ _ Hrb Hra E) as [D|D]; rewrite ?(lr_lo_group rb Hkb) in D; lia.
  - change (rmrep_shadow st m'). red. intros rid r Hr Hk.
    assert (E : rid <> fst a) by (intros E; rewrite E, Hra in Hr; congruence).
    destruct (RW rid r Hr) as (R0 & _ & _ & RC & _).
    pose proof (round_up_pg_ge (r_len r)).
    assert (DR : r_base r + round_up_pg (r_len r) <= A + 8 \/ A + 16 <= r_base r).
    { destruct (RD _ _ _ _ Hr Hra E) as [D|D]; rewrite ?(lr_lo_group r Hk) in D; lia. }
    destruct (SH rid r Hr Hk) as (HW & HS).
    split.
    + apply (OSSVerify.Proofs.boost_beast.http_request.lib.Ub.RMallocKit_A2.rwr_at_agree m m' _ _ HW). apply AG; lia.
    + intros o v Ho Hc. destruct (HS o v Ho Hc) as (Hb & Hv). split; [|exact Hv].
      apply (OSSVerify.Proofs.boost_beast.http_request.lib.Ub.RMallocKit_A2.rbytes_at_agree m m' _ _ Hb).
      change (Z.of_nat (length [b8 v])) with 1. apply AG; lia.
Qed.

